create extension if not exists pgcrypto;
create table if not exists properties(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,price numeric not null,currency text default 'USD',operation text not null check(operation in('venta','alquiler')),type text not null,city text not null,province text,sector text,land_m2 numeric,build_m2 numeric,rooms int,baths int,parking int,description text not null,features jsonb not null default '[]',images jsonb not null default '[]',video_url text,lat numeric,lng numeric,featured boolean default false,published boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists vehicles(id uuid primary key default gen_random_uuid(),slug text unique not null,brand text not null,model text not null,version text,year int not null,price numeric not null,currency text default 'USD',mileage int default 0,fuel text,transmission text,engine text,description text not null,features jsonb not null default '[]',images jsonb not null default '[]',video_url text,featured boolean default false,published boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists leads(id uuid primary key default gen_random_uuid(),name text,phone text,email text,content_id text,content_type text,message text,value numeric,source text,medium text,campaign text,content text,term text,fbclid text,gclid text,status text default 'nuevo',created_at timestamptz default now());
alter table properties enable row level security;alter table vehicles enable row level security;alter table leads enable row level security;
create policy "published properties" on properties for select using(published=true);
create policy "published vehicles" on vehicles for select using(published=true);
create policy "insert leads" on leads for insert with check(true);